            method: 'POST',
            cache: 'no-cache',
            headers: getRequestHeaders(),
            body: JSON.stringify({
                ch_name: characters[this_chid].name,
                file_name: fileName,
                chat: [chatHeader, ...trimmedChat],
                avatar_url: characters[this_chid].avatar,
                force: force,
            }),
        });
        const result = await fetch('/api/chats/save', saveChatRequest);

        if (result.ok) {
            return;
